// The Maestro flows rely on the balls of seed 42. They are generated by scripts/flows.mjs; this test recomputes the
// balls from the engine and fails on drift (fix: update SEED_42_BALLS, then `node scripts/flows.mjs`).
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

import { drawBall, emptyDraw } from '../game/draw';
import { seedFrom } from '../game/random';

const ROOT = path.join(__dirname, '..', '..');

function firstBalls(seed: number, count: number): number[] {
  let draw = emptyDraw();
  let rng = seedFrom(seed);
  for (let i = 0; i < count; i++) ({ draw, rng } = drawBall(draw, rng)!);
  return [...draw];
}

describe('e2e flows', () => {
  it('use the real first balls of seed 42', () => {
    const source = fs.readFileSync(path.join(ROOT, 'scripts', 'flows.mjs'), 'utf8');
    const match = /SEED_42_BALLS = \[([\d, ]+)\]/.exec(source);
    expect(match).not.toBeNull();
    const declared = match![1].split(',').map((n) => Number(n.trim()));
    expect(declared).toEqual(firstBalls(42, declared.length));
  });

  it('are up to date with the generator', () => {
    expect(() => execFileSync(process.execPath, [path.join(ROOT, 'scripts', 'flows.mjs'), '--check'], { cwd: ROOT })).not.toThrow();
  });
});
